const r = await tools.exec_command({cmd:"node - <<'NODE'
const fs=require('fs'),crypto=require('crypto');
const manifestBytes=fs.readFileSync('run-manifest.json');
const manifest=JSON.parse(manifestBytes);
const receiptText=fs.readFileSync('out/receipt.json','utf8');
const svg=fs.readFileSync('out/receipt.svg','utf8');
const receipt=JSON.parse(receiptText);
function canon(v){if(Array.isArray(v))return '['+v.map(canon).join(',')+']';if(v&&typeof v==='object')return '{'+Object.keys(v).sort().map(k=>JSON.stringify(k)+':'+canon(v[k])).join(',')+'}';return JSON.stringify(v)}
function sha(v){return crypto.createHash('sha256').update(v).digest('hex')}
const required=['project','agent','duration','intervention','file','test','verification','deployment','skill','evidence_count','evidence_digests','full_manifest_digest','privacy'];
const rawEvidenceScalars=[];
function scalars(v){if(v&&typeof v==='object')Object.values(v).forEach(scalars);else rawEvidenceScalars.push(String(v))}
scalars(manifest.evidence);
const combined=receiptText+'\n'+svg;
const checks={
  required_fields:required.every(k=>Object.hasOwn(receipt,k)),
  privacy_marker:receipt.privacy==='summary-only',
  unknown_preserved:receipt.deployment==='unknown',
  evidence_count:receipt.evidence_count===manifest.evidence.length,
  evidence_digests:receipt.evidence_digests.every((x,i)=>x.digest===sha(canon(manifest.evidence[i]))),
  manifest_digest:receipt.full_manifest_digest.digest===sha(manifestBytes),
  no_raw_evidence:rawEvidenceScalars.every(v=>!combined.includes(v)),
  no_private_field_names:!/(customer|codename|local[_ -]?path|evidence[^\n]*value)/i.test(combined),
  svg_dimensions:/<svg[^>]*width="1200"[^>]*height="675"/.test(svg)
};
for(const [k,v] of Object.entries(checks)) console.log(`${v?'PASS':'FAIL'} ${k}`);
if(Object.values(checks).some(v=>!v)) process.exit(1);
